        rom[504] = {18'h05e88, 29'h07d4d206, 39'h2ea6c244d4, 48'h72c7ba20f731};
        rom[505] = {18'h05e3c, 29'h07d063ab, 39'h2e971d0efe, 48'h72991b320a44};
        rom[506] = {18'h05df0, 29'h07cbf8df, 39'h2e8780b24f, 48'h726a8be3e602};
        rom[507] = {18'h05da5, 29'h07c7919f, 39'h2e77ed27ab, 48'h723c0c2db4d2};
        rom[508] = {18'h05d5a, 29'h07c32de9, 39'h2e686267fe, 48'h720d9c06a834};
        rom[509] = {18'h05d0f, 29'h07becdb7, 39'h2e58e06c39, 48'h71df3b65f8b9};
        rom[510] = {18'h05cc4, 29'h07ba7106, 39'h2e49672d57, 48'h71b0ea42e5fc};
        rom[511] = {18'h05c7a, 29'h07b617d4, 39'h2e39f6a458, 48'h7182a894b69b};
    end
    assign rc = frac[RW+K-1 -: K] >= 212;
    reg [WROM-1:0] rom_q;
    reg [RW-1:0]   w_r;
    reg            v_r;
    always @(posedge clk) begin
        if (rst) v_r <= 1'b0;
        else     v_r <= in_valid;
        rom_q <= rom[frac[RW+K-1 -: K]];
        w_r   <= frac[RW-1:0];
    end
    wire [W0-1:0] c0 = {1'b1, rom_q[W0-2:0]};
    wire [W1-1:0] c1 = rom_q[48 +: W1];
    wire [W2-1:0] c2 = rom_q[87 +: W2];
    wire [W3-Z3-1:0] c3 = rom_q[116 +: W3-Z3];

    // c0 - c1*w, the wide product, held if the chain takes longer.
    wire v_p;
    wire [W1+T1-1:0] p1;
    _zkf_pmul #(
        .WA(W1), .WB(T1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT)
    ) u_p1 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c1), .b(w_r[RW-1 -: T1]),
        .out_valid(v_p), .sb_out(), .p(p1)
    );
    wire [W0-1:0] c0_d;
    zkf_pipe #(.W(W0), .N(NK)) u_c0 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c0), .out_valid(), .out(c0_d)
    );
    wire [W1-1:0] p1_d;
    zkf_pipe #(.W(W1), .N(NK - 1 - STAGE_PRODUCT)) u_p1_d (
        .clk(clk), .rst(rst), .in_valid(v_p), .in(p1[W1+T1-1:T1]), .out_valid(out_valid), .out(p1_d)
    );

    wire [TS-1:0] ws = w_r[RW-1 -: TS];
    wire v_s;  // the valid of the square
    // The pairs c[2i] - c[2i+1]*w above the wide one, each held for its turn.
    wire [W3-Z3+T3-1:0] p3;
    _zkf_pmul #(
        .WA(W3-Z3), .WB(T3), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_ODD), .STAGE_OUTPUT(0)
    ) u_p3 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c3), .b(w_r[RW-1 -: T3]),
        .out_valid(), .sb_out(), .p(p3)
    );
    wire [W2-1:0] c2_d;
    zkf_pipe #(.W(W2), .N(STAGE_PRODUCT_ODD)) u_c2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c2), .out_valid(), .out(c2_d)
    );
    wire [W2-1:0] pair1_0 = c2_d - p3[W3-Z3+T3-1:T3-Z3];
    wire [W2-1:0] pair1;
    zkf_pipe #(.W(W2), .N(NF - STAGE_PRODUCT_ODD)) u_pair1 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(pair1_0), .out_valid(), .out(pair1)
    );
    // chain = (c2 - c3*w) * w**2, registered as the bits the last sum takes.
    // The square takes two products, the low part's own square left out.
    localparam integer TL = TS - TH;
    localparam integer BASE = 2*TS - Q0 - SG;
    wire [TH+TH-1:0] sq_hh;
    _zkf_pmul #(
        .WA(TH), .WB(TH), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(SQP), .STAGE_OUTPUT(SQO)
    ) u_sq_hh (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(ws[TS-1:TL]), .b(ws[TS-1:TL]),
        .out_valid(v_s), .sb_out(), .p(sq_hh)
    );
    localparam integer NHL = (SQP > 2) ? 2 : SQP;  // what a product this narrow admits
    wire [TH+TL-1:0] sq_hl;
    _zkf_pmul #(
        .WA(TH), .WB(TL), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(NHL), .STAGE_OUTPUT(SQO)
    ) u_sq_hl (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(ws[TS-1:TL]), .b(ws[TL-1:0]),
        .out_valid(), .sb_out(), .p(sq_hl)
    );
    wire [TH+2*TL-BASE:0] sq_hl_d;
    zkf_pipe #(.W(TH+2*TL-BASE+1), .N(SQP - NHL)) u_sq_hl_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(sq_hl[TH+TL-1 : BASE-TL-1]), .out_valid(), .out(sq_hl_d)
    );
    wire [Q0+SG-1:0] sq_s = sq_hh[2*TH-1 : BASE-2*TL] + sq_hl_d;
    wire [Q0-1:0] sq_0;
    wire v_0;
    zkf_pipe #(.W(Q0), .N(NF - STAGE_PRODUCT_SQUARE)) u_sq_0 (
        .clk(clk), .rst(rst), .in_valid(v_s), .in(sq_s[Q0+SG-1:SG]), .out_valid(v_0), .out(sq_0)
    );
    wire [W2+Q0-1:0] p2;
    _zkf_pmul #(
        .WA(W2), .WB(Q0), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p2 (
        .clk(clk), .rst(rst), .in_valid(v_0), .sb_in(1'b0), .a(pair1), .b(sq_0),
        .out_valid(), .sb_out(), .p(p2)
    );
    wire [W2-1:0] p2_d;
    zkf_pipe #(.W(W2), .N(NK - NL)) u_p2_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(p2[W2+Q0-1:Q0]), .out_valid(), .out(p2_d)
    );
    reg  [W2-1:0] chain;
    always @(posedge clk) chain <= p2_d;
    assign c = c0_d - p1_d + chain;
endmodule

// verilog_lint: waive-stop line-length
`default_nettype wire
